<script setup lang="ts">
import { computed } from 'vue'
import type { Trade } from '../../types'
import { useKronosStore } from '../../stores'
import { money, number, percent, date } from '../../format'
import StatusBadge from '../../components/StatusBadge.vue'
const props=defineProps<{trade:Trade}>();defineEmits<{select:[trade:Trade]}>();const kronos=useKronosStore()
const linkedKronos=computed(()=>kronos.view?.latest?.prediction_id===props.trade.signalId?kronos.view.latest:null)
</script>
<template><article class="card open-trade-card" :class="{paper:trade.classification==='BROKER_PAPER_EXECUTION'}" data-testid="open-trade-card"><div class="panel-heading"><div><span class="eyebrow">{{ trade.classification==='BROKER_PAPER_EXECUTION'?'IBKR PAPER':trade.classification==='SIMULATED_SHADOW'?'SIMULATED SHADOW':'ORIGEN SIN CLASIFICAR' }}</span><h3>{{ trade.symbol }} · {{ trade.profile }} · {{ trade.direction }}</h3></div><StatusBadge :value="trade.status" /></div><div class="position-pnl"><span>P&L neto {{ trade.closedAt?'realizado':'estimado' }}</span><strong>{{ money(trade.netPnl) }}</strong><span>Comisión {{ trade.commissionStatus }} · {{ money(trade.commission) }}</span></div><dl class="position-grid"><div><dt>Entry</dt><dd>{{ number(trade.entry,5) }}</dd></div><div><dt>Current</dt><dd>{{ number(trade.currentPrice,5) }}</dd></div><div><dt>Stop</dt><dd>{{ number(trade.stop,5) }}</dd></div><div><dt>Target</dt><dd>{{ number(trade.target,5) }}</dd></div><div><dt>Size</dt><dd>{{ number(trade.quantity) }}</dd></div><div><dt>Gross P&L · USD</dt><dd>{{ money(trade.grossPnl) }}</dd></div><div><dt>Probabilidad empírica</dt><dd>{{ percent(trade.probability) }}</dd></div><div><dt>EV · USD</dt><dd>{{ money(trade.expectedValue) }}</dd></div><div><dt>Regime</dt><dd>{{ trade.regime }}</dd></div><div><dt>Duration · s</dt><dd>{{ number(trade.durationSeconds,0) }}</dd></div><div><dt>Kronos vinculado</dt><dd>{{ linkedKronos?.prediction_id ?? 'UNKNOWN · sin vínculo registrado' }}</dd></div><div><dt>Protección</dt><dd>{{ trade.protection }}</dd></div></dl><p class="small muted">{{ date(trade.openedAt) }} · {{ trade.strategyVersion }} · {{ trade.entryReason }}</p><button class="secondary-button" @click="$emit('select',trade)">Ver evidencia de la operación</button></article></template>
